"use client"

import { User } from "lucide-react"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

interface ProfileDropdownProps {
  userMode: "parent" | "child"
  onModeChange: (mode: "parent" | "child") => void
}

export function ProfileDropdown({ userMode, onModeChange }: ProfileDropdownProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger className="flex items-center gap-2 px-4 py-2 rounded-lg hover:bg-accent hover:text-accent-foreground transition-colors">
        <User className="w-5 h-5" />
        <span className="font-medium">My Profile</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem 
          onClick={() => onModeChange("parent")}
          className={userMode === "parent" ? "bg-secondary text-secondary-foreground" : ""}
        >
          Parent View
        </DropdownMenuItem>
        <DropdownMenuItem 
          onClick={() => onModeChange("child")}
          className={userMode === "child" ? "bg-accent text-accent-foreground" : ""}
        >
          Child View
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}