"use client"

import {
  ArrowRight,
  CheckCircle2,
  Clock,
  Sparkles,
  AlertTriangle,
  Info,
} from "lucide-react"
import { useState } from "react"

// 1. Define a type for your JSON data
interface Alert {
  timestamp: string
  privacy_safe_message: string
  parent_suggestion: string
  type?: "event"
  severity?: "severe" | "normal"
  is_event?: boolean
}

// 2. Hard-code the JSON data directly into the file
// This avoids all "Failed to fetch" errors.
const alertsData: Alert[] = [
  {
    timestamp: "2025-11-09T06:39:56.101854",
    is_event: true,
    privacy_safe_message: "Your child has a math test today.",
    parent_suggestion: "Wish them luck!",
    type: "event",
  },
  {
    timestamp: "2025-11-09T06:40:44.863476",
    severity: "severe",
    privacy_safe_message: "It sounds like Ron might be feeling a bit sad today.",
    parent_suggestion:
      "A gentle check-in or a warm message could make a difference.",
  },
]

// A helper function to get the right icon
function getAlertIcon(alert: Alert) {
  if (alert.type === "event" || alert.is_event) {
    return <Sparkles className="w-6 h-6 text-secondary" />
  }
  if (alert.severity === "severe") {
    return <AlertTriangle className="w-6 h-6 text-destructive" />
  }
  // Default icon for other types
  return <Info className="w-6 h-6 text-blue-500" />
}

export function ParentHomeTab() {
  // We sort the data here (newest first)
  const alerts = alertsData.sort(
    (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
  )

  return (
    <div className="space-y-6">
      {/* Greeting (remains static) */}
      <div>
        <h1 className="text-4xl font-bold text-foreground mb-2">
          Good morning, Arthur
        </h1>
        <p className="text-muted-foreground">
          Today looks like a great day to connect
        </p>
      </div>

      {/* Dynamic Alerts Section */}
      <div className="bg-white rounded-2xl p-6 border border-border shadow-sm hover:shadow-md transition-shadow">
        <h3 className="font-semibold text-foreground mb-4">Recent Updates</h3>

        {/* Render Dynamic Cards */}
        {alerts.length > 0 ? (
          <div className="space-y-4">
            {alerts.map((alert) => (
              <div
                key={alert.timestamp}
                className="flex items-start gap-4 pb-4 border-b border-border last:border-0 last:pb-0"
              >
                <div className="w-12 h-12 rounded-xl bg-muted/50 flex items-center justify-center flex-shrink-0">
                  {getAlertIcon(alert)}
                </div>
                <div className="flex-1">
                  <p className="font-semibold text-foreground mb-1">
                    {alert.privacy_safe_message}
                  </p>
                  <p className="text-muted-foreground text-sm mb-4">
                    {alert.parent_suggestion}
                  </p>

                  {/* Add button conditionally for events */}
                  {(alert.type === "event" || alert.is_event) && (
                    <button className="inline-flex items-center gap-2 bg-secondary hover:bg-secondary/90 text-secondary-foreground px-4 py-2 rounded-lg font-medium transition-all active:scale-95 hover:shadow-md">
                      🚀 Send Good Luck!
                      <ArrowRight className="w-4 h-4" />
                    </button>
                  )}

                  {/* Show a different action for severe alerts */}
                  {alert.severity === "severe" && (
                    <button className="inline-flex items-center gap-2 bg-destructive/10 hover:bg-destructive/20 text-destructive px-4 py-2 rounded-lg font-medium transition-all active:scale-95">
                      ❤️ Send a Message
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          // Handle Empty State
          <p className="text-muted-foreground text-sm">
            No new updates from Tim's world right now.
          </p>
        )}
      </div>

      {/* Guide's Corner (remains static for now) */}
      <div className="bg-white rounded-2xl p-6 border border-border shadow-sm hover:shadow-md transition-all">
        <div className="flex items-start gap-4">
          <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
            <Clock className="w-6 h-6 text-primary" />
          </div>
          <div className="flex-1">
            <h3 className="font-semibold text-foreground mb-1">
              Guide's Corner
            </h3>
            <p className="text-muted-foreground text-sm mb-4">
              Your Guide suggests a 15-min chat with Tim tonight. You're both
              free around 6:30 PM.
            </p>
            <button className="px-4 py-2 rounded-lg font-medium text-primary bg-primary/10 hover:bg-primary/20 transition-all active:scale-95">
              Ask Guide for help
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}