
import Image from "next/image";

const randomEvents = [
  "Football match with friends",
  "Baking cookies",
  "Mountain hiking adventure",
  "Family picnic",
  "Art class masterpiece",
  "Science fair project",
  "Cooking pasta night",
  "Beach volleyball",
  "Camping under stars",
  "Gardening day",
  "Book reading marathon",
  "Making paper planes",
  "Birthday celebration",
  "Exploring the zoo",
  "Painting peacock feathers"
];

function getRandomEvent(i: number) {
  return randomEvents[i % randomEvents.length];
}

export function Gallery({ photos }: { photos: string[] }) {
  // We'll render a 3x3 grid of polaroids. Each card gets a slight rotation for an organic look
  const rotations = [-6, -3, 2, 5, -4, 7, -2, 4, -5];

   return (
     <div className="relative min-h-[95vh] w-full bg-blackboard overflow-x-hidden overflow-y-auto pb-20 z-0">
      {/* Blackboard border effect */}
      <div className="absolute inset-0 border-8 border-[#3a2f23] rounded-3xl pointer-events-none" style={{boxShadow:'0 0 60px 10px #111 inset', zIndex:2}}></div>

       <div className="relative w-full max-w-[1200px] mx-auto py-8 px-6">
  <div className="grid grid-cols-3 auto-rows-auto content-start" style={{rowGap: '2rem', columnGap: '1.5rem'}}>
          {photos.slice(0,9).map((src, i) => (
            <div
              key={i}
              className="polaroid-wrapper-memories flex justify-center"
              style={{ ['--rot' as any]: `${rotations[i % rotations.length]}deg` }}
            >
              <div className="flex flex-col items-center">
                {/* Wooden clip */}
                <div className="w-8 h-4 bg-yellow-800 rounded-t-md shadow-md mb-1" style={{marginBottom: '-8px'}}></div>
                {/* Tape */}
                <div className="polaroid-tape-memories" aria-hidden />
                <div className="polaroid-memories">
                  <Image
                    src={src}
                    alt={`Gallery photo ${i+1}`}
                    width={200}
                    height={200}
                    className="object-cover rounded"
                    style={{boxShadow:'0 6px 18px rgba(0,0,0,0.35)'}}
                  />
                  <div className="polaroid-caption-memories caveat-memories">
                    {getRandomEvent(i)}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Gallery;
