"use client"

import { Mic, Send } from "lucide-react"
import { useState } from "react"

interface GuideTabProps {
  userMode: "parent" | "child"
}

// Define the API response structure for the chat
interface ChatApiResponse {
  response: string
}

export function GuideTab({ userMode }: GuideTabProps) {
  const [messages, setMessages] = useState<Array<{ id: string; type: "bot" | "user"; content: string }>>([
    {
      id: "1",
      type: "bot",
      content:
        userMode === "parent"
          ? "Hi Sarah! I'm here to help you stay connected with Tim. What can I assist you with today?"
          : "Hi Tim! Your guide here to help. How are you feeling today?",
    },
  ])
  const [inputValue, setInputValue] = useState("")
  const [isLoading, setIsLoading] = useState(false)

  // A helper function to play audio from a Blob
  const playAudioBlob = (blob: Blob) => {
    const url = URL.createObjectURL(blob)
    const audio = new Audio(url)
    
    // Play the audio
    audio.play()

    // Clean up the object URL after the audio has finished
    audio.onended = () => {
      URL.revokeObjectURL(url)
    }
  }

  /**
   * Handles sending a TEXT message.
   * This now calls BOTH /api/chat (for text) and /api/tts (for audio)
   */
  const submitMessage = async (content: string) => {
    if (!content.trim() || isLoading) return

    // 1. Add user message to UI
    const userMessage = { id: Date.now().toString(), type: "user" as const, content }
    setMessages((prev) => [...prev, userMessage])
    setIsLoading(true)

    // Define API endpoints
    const chatApiUrl = "http://127.0.0.1:5000/api/chat"
    const ttsApiUrl = "http://127.0.0.1:5000/api/tts"

    // Define the request payload
    const payload = {
      role: userMode,
      message: content,
    }

    try {
      // 2. Call both APIs simultaneously
      const [chatResponse, ttsResponse] = await Promise.all([
        // API call for the text response
        fetch(chatApiUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }),
        // API call for the audio response
        fetch(ttsApiUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }),
      ])

      // 3. Check if both responses are OK
      if (!chatResponse.ok) throw new Error("Chat API call failed")
      if (!ttsResponse.ok) throw new Error("TTS API call failed")

      // 4. Process the responses
      const chatData: ChatApiResponse = await chatResponse.json()
      const audioData: Blob = await ttsResponse.blob() // Get audio as a Blob
      // 5. Add bot's text reply to UI
      const botResponse = {
        id: (Date.now() + 1).toString(),
        type: "bot" as const,
        content: chatData['response'] || "I'm not sure how to respond to that.",
      }
      setMessages((prev) => [...prev, botResponse])

      // 6. Play the bot's audio reply
      playAudioBlob(audioData)

    } catch (error) {
      console.error("Failed to send message:", error)
      setMessages((prev) => [
        ...prev,
        { id: "error", type: "bot", content: "Oops! Something went wrong." },
      ])
    } finally {
      setIsLoading(false)
    }
  }

  // --- UI Event Handlers ---

  // Called by the Send button
  const handleSend = () => {
    submitMessage(inputValue)
    setInputValue("") // Clear input after sending
  }

  // Called by the quick reply chips
  const handleQuickReply = (reply: string) => {
    submitMessage(reply)
  }

  // --- Quick Replies Data ---
  const quickReplies =
    userMode === "parent"
      ? [
          "Help me schedule time",
          "What's Tim interested in?",
          "Give me a conversation starter",
          "Tips for homework help",
        ]
      : ["I'm bored", "Tell me a joke", "I want to tell Mom something", "I feel sad"]

  return (
    <div className="flex flex-col h-[calc(100vh-200px)] bg-background rounded-2xl">
      {/* Header */}
      <div className="px-6 py-4 border-b border-border">
        <h2 className="text-2xl font-bold text-foreground">Your Guide</h2>
      </div>

      {/* Chat Stream */}
      <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
        {messages.map((message) => (
          <div key={message.id} className={`flex ${message.type === "user" ? "justify-end" : "justify-start"}`}>
            <div
              className={`max-w-xs px-4 py-3 rounded-2xl ${
                message.type === "bot"
                  ? "bg-muted text-foreground"
                  : userMode === "parent"
                    ? "bg-secondary text-secondary-foreground"
                    : "bg-accent text-accent-foreground"
              }`}
            >
              <p className="text-sm">{message.content}</p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="max-w-xs px-4 py-3 rounded-2xl bg-muted text-foreground">
              <p className="text-sm italic">Typing...</p>
            </div>
          </div>
        )}
      </div>

      {/* Quick Reply Chips */}
      {messages.length > 0 && (
        <div className="px-6 py-3 border-t border-border overflow-x-auto">
          <div className="flex gap-2 flex-nowrap">
            {quickReplies.map((reply) => (
              <button
                key={reply}
                onClick={() => handleQuickReply(reply)}
                disabled={isLoading}
                className="flex-shrink-0 px-3 py-2 bg-muted hover:bg-muted/80 text-foreground rounded-full text-xs font-medium transition-colors whitespace-nowrap disabled:opacity-50"
              >
                {reply}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Input Bar */}
      <div className="border-t border-border p-4 flex items-center gap-3">
        <button
          // Note: This button currently does nothing.
          // You would need to add Speech-to-Text logic here.
          onClick={() => console.log("Mic button clicked - add STT logic here")}
          disabled={isLoading}
          className="p-2 hover:bg-muted rounded-lg transition-colors text-muted-foreground hover:text-foreground disabled:opacity-50"
        >
          <Mic className="w-5 h-5" />
        </button>
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={(e) => e.key === "Enter" && !isLoading && handleSend()}
          placeholder={userMode === "parent" ? "Ask your Guide for help..." : "Tell your Guide how you feel..."}
          className="flex-1 px-4 py-2 bg-muted rounded-lg text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary"
          disabled={isLoading}
        />
        <button
          onClick={handleSend}
          disabled={!inputValue.trim() || isLoading}
          className="p-2 bg-primary hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg transition-colors text-foreground"
        >
          <Send className="w-5 h-5" />
        </button>
      </div>
    </div>
  )
}